steps.script:
var mn = tree.root.get_node("Main")
if mn._phase_end_confirm != null and mn._phase_end_confirm.visible:
	mn._phase_end_confirm.get_ok_button().pressed.emit()
return true

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var n := 0
while f != null and not f.eof_reached():
	var l := f.get_line()
	if l.contains("[ERROR"):
		n += 1
		print("[sm11e-m4c] debug-log ERROR: ", l)
return n
